"use strict";(self.webpackChunkuniplus_developers=self.webpackChunkuniplus_developers||[]).push([["59261"],{89466(e){e.exports=JSON.parse('{"registro":{"codigo":"uniplus.selecao.criterio_desempate.regra_nao_encontrada","status":422,"titulo":"Regra de desempate n\xe3o encontrada no cat\xe1logo de regras"},"descricao":{"codigo":"uniplus.selecao.criterio_desempate.regra_nao_encontrada","requisitos":["UNI-REQ-0015"],"oQueAconteceu":["O `regraCodigo`/`regraVersao` de um dos crit\xe9rios de desempate do corpo do pedido\\nn\xe3o existe no `rol_de_regras` \u2014 o mesmo cat\xe1logo interno ao m\xf3dulo Sele\xe7\xe3o\\nde onde v\xeam as demais regras tipadas do processo (distribui\xe7\xe3o de vagas,\\najuste, cascata de remanejamento). Esta resolu\xe7\xe3o s\xf3 roda depois que a\\npassada de forma (ordem de todos os crit\xe9rios) vem inteiramente limpa \u2014 ver\\n[`ordem_invalida`](/erros/uniplus.selecao.criterio_desempate.ordem_invalida).","O processamento \xe9 sequencial por crit\xe9rio: o primeiro que falhar interrompe\\na passada \u2014 os crit\xe9rios seguintes do mesmo corpo do pedido n\xe3o chegam a ser\\nconferidos, e a resposta traz s\xf3 esta viola\xe7\xe3o, sem acumular com nenhuma\\noutra.","Esta causa n\xe3o aparece na leitura de vers\xf5es j\xe1 publicadas, inclusive na retifica\xe7\xe3o em ato \xfanico: a vers\xe3o guarda c\xf3digo, vers\xe3o e hash da regra, sem consultar novamente o `rol_de_regras`."],"comoResolver":["Confirme, no cat\xe1logo de regras, que o c\xf3digo e a vers\xe3o do crit\xe9rio de\\ndesempate declarados existem. Se a regra foi descontinuada recentemente, ou\\no c\xf3digo est\xe1 incorreto, corrija o corpo do pedido antes de reenviar.","Como o processamento para no primeiro crit\xe9rio com problema, corrigir este\\ne reenviar pode revelar uma nova falha num crit\xe9rio seguinte do mesmo\\ncorpo do pedido \u2014 n\xe3o \xe9 garantia de que o restante do corpo do pedido est\xe1 correto."],"ondeAparece":["Defini\xe7\xe3o de crit\xe9rios de desempate do processo seletivo"]},"modulo":{"id":"selecao","nome":"Sele\xe7\xe3o","assunto":"Criterio desempate"},"origem":{"repositorio":"unifesspa-edu-br/uniplus-api","commit":"38e6e984f8a69f1cdfcd140295a410206c687849"}}')}}]);